INSERT INTO tb_search_keyword_daily (stat_date, keyword, searchers, zero_result_searchers)
SELECT #{day}, target_key, COUNT(*), COUNT(*) FILTER (WHERE zero_result)
  FROM tb_usage_events
 WHERE event_date = #{day}
   AND event_type = 'SEARCH'
   AND target_key <> #{masked}
 GROUP BY target_key
HAVING COUNT(*) >= #{minSearchers}

mapper.select:
SELECT 
  FROM tb_usage_daily_stats s
 WHERE s.stat_date BETWEEN #{from} AND #{to}

SELECT member_type, gender, age_band, SUM(count) AS count
  FROM tb_usage_daily_stats
 WHERE metric = #{metric}
   AND stat_date BETWEEN #{from} AND #{to}
 GROUP BY member_type, gender, age_band
